app.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='start-form'){const f=new FormData(e.target);const raw=String(f.get('code')||'').trim(),code=raw?E.parseSeasonCode(raw):null;if(raw&&!code){notify(t('code.invalid'),{type:'error'});play('error');$('#code')?.focus();return;}if(state&&!await confirmDialog(t('confirm.replace'),{yes:t('confirm.replaceYes'),danger:true}))return;state=E.createGame(data,f.get('coach'),code?code.difficulty:f.get('difficulty'),code?code.seed:undefined);E.autoLineup(state);save();play('whistle');view='home';try{if(!localStorage.getItem(TUTORIAL)){tutorial=1;localStorage.setItem(TUTORIAL,'seen');}}catch{tutorial=1;}render();$('main h1')?.focus({preventScroll:true});}});
